'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),model=require('./velen-routing.js'),data=require('./velen-data-r18.js');
test('historical Velen console, hubs, stages and leads enter the same shared view',()=>{for(const route of ['#hub/nilf','#quest/nilf/4','#quest/pyres/2','#lead/baron','#merchants','#deferred']){assert.equal(model.sharedHash(route),'#velen/'+route.slice(1));assert.equal(model.sharedHash(model.sharedHash(route)),model.sharedHash(route));}assert.deepEqual(model.parse('#velen/quest/nilf/4'),{type:'quest',id:'nilf',stage:'4'});assert.equal(model.sharedHash('#velen'),'#velen');assert.equal(model.sharedHash('#not-a-route'),'#velen');});
test('saved legacy Continue destinations normalize without accepting unknown quests or impossible stages',()=>{assert.equal(model.resumeHref('velen.html#quest/nilf/4',data.quests),'#velen/quest/nilf/4');assert.equal(model.resumeHref('#velen/quest/pyres/2',data.quests),'#velen/quest/pyres/2');for(const href of ['velen.html#quest/nilf/99','velen.html#quest/unknown/1','https://example.com/#quest/nilf/1','javascript:alert(1)'])assert.equal(model.resumeHref(href,data.quests),null);});
test('entry and pointer navigation never force heading focus, while deliberate keyboard navigation can',()=>{for(const mode of ['initial','push','pop','hash'])assert.equal(model.shouldFocus(mode,'pointer'),false);assert.equal(model.shouldFocus('initial','keyboard'),false);assert.equal(model.shouldFocus('pop','keyboard'),false);assert.equal(model.shouldFocus('push','keyboard'),true);});
test('shared history restores the recorded hub and back positions without applying stale return Y to a new page',()=>{assert.equal(model.restoreY('pop',{pageY:421,velen:{restoreY:98}}),421);assert.equal(model.restoreY('push',{pageY:421,velen:{restoreY:98}}),98);assert.equal(model.restoreY('push',{pageY:421}),0);assert.equal(model.restoreY('pop',{pageY:-3}),0);assert.equal(model.restoreY('pop',{pageY:Infinity}),0);});
test('route conversion leaves legacy completion, choices and Undo ownership unchanged',()=>{const raw={complete:{nilf:true,pyres:false,mercy:true},choices:{inn:'peace'},stage:{nilf:3,pyres:2,mercy:1},selected:'mercy',lastHub:'nilf'},before=JSON.stringify(raw),state=data.initial(raw),snapshot=JSON.stringify(state);for(const href of ['#velen','#hub/nilf','#quest/mercy/1'])model.parse(model.sharedHash(href));assert.equal(JSON.stringify(raw),before);assert.equal(JSON.stringify(state),snapshot);assert.equal(state.complete.nilf,true);assert.equal(state.complete.mercy,true);assert.equal(state.complete.pyres,false);assert.equal(state.stage.nilf,3);assert.equal(state.choices.inn,'peace');});
